function Fact({l,v}:{l:string;v:string}){return <div><small>{l}</small><b>{v}</b></div>}

function ProductIdentity({handoff,onReturn}:{handoff?:any;onReturn:()=>void}){
 const [lookup,setLookup]=useState<any>(null); const [looking,setLooking]=useState(false); const [amazonPackQty,setAmazonPackQty]=useState(1); const [suggestions,setSuggestions]=useState<any[]>([]); const [matchStats,setMatchStats]=useState({strong:0,review:0,newProducts:0,unlinked:0}); const [suggestionsLoading,setSuggestionsLoading]=useState(true); const [suggestionBusy,setSuggestionBusy]=useState(''); const [asinCheck,setAsinCheck]=useState<any>(null); const [sasCopied,setSasCopied]=useState(false); const [completed,setCompleted]=useState<string[]>([]); const [saved,setSaved]=useState<Record<string,any>>({}); const [saving,setSaving]=useState(false); const [q,setQ]=useState(''); const [status,setStatus]=useState<'all'|'review'|'unmatched'|'completed'>('all'); const [supplier,setSupplier]=useState('All suppliers'); const [items,setItems]=useState<any[]>([]); const [loading,setLoading]=useState(true); const [selected,setSelected]=useState<any>(null); const [draft,setDraft]=useState({ean:'',asin:'',brand:'',size:''})
 useEffect(()=>{(async()=>{try{const sr=await fetch('/api/identity-suggestions',{cache:'no-store'}),sj=await sr.json();if(sj.ok){setSuggestions(sj.suggestions||[]);setMatchStats({strong:sj.strongCount||0,review:sj.reviewCount||0,newProducts:sj.newCount||0,unlinked:sj.unlinkedOffers||0})}const ir=await fetch('/api/product-identity',{cache:'no-store'}),ij=await ir.json();if(ij.ok){const m:Record<string,any>={};(ij.identities||[]).forEach((z:any)=>{m[z.supplier+'-'+z.supplier_offer_id]=z});setSaved(m);setCompleted((ij.identities||[]).filter((z:any)=>z.status==='completed').map((z:any)=>z.supplier+'-'+z.supplier_offer_id))}const slugs=['stateside','sweet-glory','wholesale-sweets','kings-candy'];const rs=await Promise.all(slugs.map(s=>fetch('/api/suppliers/catalogue?supplier='+s,{cache:'no-store'})));const ds=await Promise.all(rs.map(r=>r.json()));setItems(ds.flatMap(d=>d.ok&&Array.isArray(d.offers)?d.offers:[]).map((x:any)=>({...x,identity:x.ean&&x.ean!=='NEEDS MATCH'?'review':'unmatched',asin:x.asin||''}))) }finally{setLoading(false);setSuggestionsLoading(false)}})()},[])
 useEffect(()=>{if(!handoff||!items.length)return;const target=handoff.best||handoff;const targetSupplier=target.supplier||target.source||'';const targetEan=target.ean&&target.ean!=='NEEDS MATCH'?String(target.ean):'';const targetId=String(target.supplierProductId||target.id||'');const match=items.find((x:any)=>(targetId&&String(x.supplierProductId||x.id)===targetId&&(x.supplier||x.source)===targetSupplier)||(targetEan&&String(x.ean||'')===targetEan&&(x.supplier||x.source)===targetSupplier))||items.find((x:any)=>targetEan&&String(x.ean||'')===targetEan);if(match){setQ(targetEan||match.product||'');setSupplier(match.supplier||match.source||'All suppliers');open(match)}},[handoff,items])
 const confirmSuggestion=async(s:any)=>{const key=s.offer.supplier+'-'+s.offer.supplier_product_id;setSuggestionBusy(key);try{const r=await fetch('/api/identity-suggestions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({identityId:s.identity.id,supplier:s.offer.supplier,supplierOfferId:s.offer.supplier_product_id,score:s.score,reason:s.reason,action:'confirm'})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Unable to confirm match');setSuggestions(v=>v.filter(z=>z!==s))}catch(e:any){alert(e?.message||'Unable to confirm match')}finally{setSuggestionBusy('')}}
 const rejectSuggestion=async(s:any)=>{const key=s.offer.supplier+'-'+s.offer.supplier_product_id;setSuggestionBusy(key);try{const r=await fetch('/api/identity-suggestions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({identityId:s.identity.id,supplier:s.offer.supplier,supplierOfferId:s.offer.supplier_product_id,score:s.score,reason:s.reason,action:'reject'})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Unable to reject match');setSuggestions(v=>v.filter(z=>z!==s))}catch(e:any){alert(e?.message||'Unable to reject match')}finally{setSuggestionBusy('')}}
 const suppliers=['All suppliers',...Array.from(new Set(items.map(x=>x.supplier||x.source).filter(Boolean)))]
 const filtered=items.filter(x=>{const key=(x.supplier||x.source)+'-'+String(x.supplierProductId||x.id),z=saved[key],isCompleted=completed.includes(key);return (status==='completed'?isCompleted:status==='all'?true:!isCompleted&&x.identity===status)&&(supplier==='All suppliers'||(x.supplier||x.source)===supplier)&&((x.product||'')+' '+(z?.brand||x.brand||'')+' '+(z?.ean||x.ean||'')+' '+(z?.asin||x.asin||'')).toLowerCase().includes(q.toLowerCase())})
 const cleanSasSearch=(x:any)=>String(x.product||x.rawTitle||'').replace(/\s+/g,' ').replace(/\s*[-–—|]+\s*/g,' ').trim()
 const openSellerAmp=async(x:any)=>{const term=cleanSasSearch(x);try{await navigator.clipboard.writeText(term);setSasCopied(true);setTimeout(()=>setSasCopied(false),1800)}catch{}window.open('https://sas.selleramp.com','_blank','noopener,noreferrer')}
 const open=(x:any)=>{setSelected(x);setLookup(null);setAsinCheck(null);setSasCopied(false);setAmazonPackQty(1);const z=saved[(x.supplier||x.source)+'-'+(x.supplierProductId||x.id)];setDraft({ean:z?.ean||(x.ean&&x.ean!=='NEEDS MATCH'?x.ean:''),asin:z?.asin||x.asin||'',brand:z?.brand||x.brand||'',size:z?.size||x.size||''})}
 function checkAsin(x:any){if(!draft.asin)return;const exact=lookup?.asin&&lookup.asin.toUpperCase()===draft.asin.toUpperCase();const barcode=!!lookup?.checks?.barcode;setAsinCheck({status:exact&&barcode?'HIGH':barcode?'REVIEW':'MANUAL',message:exact&&barcode?'ASIN matches the barcode lookup candidate.':barcode?'Barcode is verified, but this ASIN differs from the lookup candidate. Review the Amazon listing before completing.':'ASIN entered. Verify the Amazon listing against the exact product before completing.'})}
 async function complete(x:any){const supplier=x.supplier||x.source,offerId=String(x.supplierProductId||x.id),key=supplier+'-'+offerId,isEdit=completed.includes(key);if(!draft.ean||!draft.asin||(!asinCheck&&!isEdit))return;setSaving(true);try{const r=await fetch('/api/product-identity',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({supplier,supplierOfferId:offerId,product:x.product,brand:draft.brand,size:draft.size,ean:draft.ean,asin:draft.asin,status:'completed',eanConfidence:lookup?.confidence||null,asinConfidence:asinCheck?.status||saved[key]?.asin_confidence||'MANUAL'})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Save failed');setSaved(v=>({...v,[key]:d.identity}));setCompleted(v=>v.includes(key)?v:[...v,key]);setSelected(null)}catch(e:any){alert(e?.message||'Unable to save Product Identity')}finally{setSaving(false)}}
 async function createMaster(x:any){if(!draft.asin)return;const supplier=x.supplier||x.source,offerId=String(x.supplierProductId||x.id);setSaving(true);try{const r=await fetch('/api/master-identities',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({productName:x.product,brand:draft.brand,size:draft.size,unitSize:draft.size,ean:draft.ean,asin:draft.asin,countryOrigin:x.countryOrigin||'',supplier,supplierOfferId:offerId,amazonPackQty})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Unable to create master identity');setCompleted(v=>v.includes(supplier+'-'+offerId)?v:[...v,supplier+'-'+offerId]);setSelected(null)}catch(e:any){alert(e?.message||'Unable to create master identity')}finally{setSaving(false)}}
 async function barcodeLookup(x:any){if(!draft.ean)return;setLooking(true);setLookup(null);try{const r=await fetch('/api/product-identity/barcode?ean='+encodeURIComponent(draft.ean)+'&title='+encodeURIComponent(x.product||'')+'&brand='+encodeURIComponent(x.brand||'')+'&size='+encodeURIComponent(x.size||''));const d=await r.json();setLookup(d.ok?d.candidate:{error:d.error||'No match found'})}catch{setLookup({error:'Lookup failed'})}finally{setLooking(false)}}
 return <><div className="catalogueHero"><Title k="PRODUCT DATA" t="Product Identity" p="Work through products already pulled from your supplier catalogues. Verify the barcode, add the Amazon ASIN and build a trusted master product record."/><div className="catalogueActions">{handoff&&<button className="secondaryAction" onClick={onReturn}>← Back to Finn</button>}<span className="identityBadge review">{loading?'LOADING SUPPLIERS…':items.length+' SUPPLIER PRODUCTS'}</span></div></div>
 <div className="catalogueStats"><button className="metric" onClick={()=>setStatus('all')}><span>All products</span><strong>{items.length}</strong><small>supplier identity records</small></button><button className="metric" onClick={()=>setStatus('review')}><span>To review</span><strong>{items.filter(x=>!completed.includes((x.supplier||x.source)+'-'+String(x.supplierProductId||x.id))&&x.identity==='review').length}</strong><small>EAN supplied · needs matching</small></button><button className="metric" onClick={()=>setStatus('unmatched')}><span>Missing EAN</span><strong>{items.filter(x=>!completed.includes((x.supplier||x.source)+'-'+String(x.supplierProductId||x.id))&&x.identity==='unmatched').length}</strong><small>barcode needs finding</small></button><button className="metric" onClick={()=>setStatus('completed')}><span>Completed</span><strong>{completed.length}</strong><small>saved · click to review or edit</small></button></div>
 <section className="catalogueSection"><div className="overviewSectionHead"><div><small>FAST MATCHING</small><h2>Suggested matches</h2><p>Flip Lead compares unlinked wholesale offers with products you have already verified. Confirm the same product once instead of researching it again.</p></div><span className="identityBadge review">{suggestionsLoading?'SCANNING…':matchStats.unlinked+' NEED ATTENTION'}</span></div><div className="catalogueStats"><div className="metric"><span>Strong match</span><strong>{matchStats.strong}</strong><small>quick confirm</small></div><div className="metric"><span>Review</span><strong>{matchStats.review}</strong><small>check ambiguity</small></div><div className="metric"><span>New products</span><strong>{matchStats.newProducts}</strong><small>research once</small></div></div>
 {suggestionsLoading?<div className="emptyState"><b>Comparing supplier offers…</b><span>Checking EAN, product name, brand and size against your trusted identities.</span></div>:suggestions.length===0?<div className="emptyState"><b>No suggested matches waiting.</b><span>New matches will appear here as supplier catalogues and verified identities grow.</span></div>:<div className="catalogueTable"><table><thead><tr><th>Wholesale offer</th><th>Suggested Product Identity</th><th>Confidence</th><th>Why</th><th>Action</th></tr></thead><tbody>{suggestions.slice(0,50).map((s:any)=>{const k=s.offer.supplier+'-'+s.offer.supplier_product_id;return <tr key={k}><td><div className="productCell"><b>{s.offer.product}</b><span>{s.offer.supplier}{s.offer.size?' · '+s.offer.size:''}</span></div></td><td><div className="productCell"><b>{s.identity.product_name}</b><span>{s.identity.brand||'Brand not set'}{s.identity.size?' · '+s.identity.size:''}{s.identity.asin?' · '+s.identity.asin:''}</span></div></td><td><strong className={'confidence '+(s.score>=90?'high':s.score>=70?'medium':'low')}>{s.score}% · {s.band}</strong></td><td><small>{s.reason||'Similar product data'}</small></td><td><div className="quick"><button className="primary" disabled={suggestionBusy===k} onClick={()=>confirmSuggestion(s)}>{suggestionBusy===k?'Saving…':'Confirm'}</button><button disabled={suggestionBusy===k} onClick={()=>rejectSuggestion(s)}>Not same</button></div></td></tr>})}</tbody></table></div>}
 </section>
 <section className="catalogueSection"><div className="overviewSectionHead"><div><small>IDENTITY WORK QUEUE</small><h2>Work through supplier products</h2><p>The supplier catalogue stays untouched. Product Identity matches are saved separately and completed records remain searchable and editable.</p></div><div className="catalogueSearch"><select value={supplier} onChange={e=>setSupplier(e.target.value)}>{suppliers.map(s=><option key={s}>{s}</option>)}</select><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search product, EAN, ASIN or brand…"/></div></div>
 <div className="catalogueTable"><table><thead><tr><th>Product</th><th>Supplier</th><th>Size</th><th>EAN / UPC</th><th>ASIN</th><th>Identity</th><th></th></tr></thead><tbody>{filtered.map(x=><Fragment key={(x.supplier||x.source)+'-'+x.id}><tr className="identityQueueRow" onClick={()=>selected?.id===x.id&&(selected.supplier||selected.source)===(x.supplier||x.source)?setSelected(null):open(x)}><td><div className="productCell"><b>{x.product}</b><span>{x.brand||'Brand not supplied'}</span></div></td><td>{x.supplier||x.source}</td><td>{saved[(x.supplier||x.source)+'-'+String(x.supplierProductId||x.id)]?.size||x.size||'—'}</td><td>{saved[(x.supplier||x.source)+'-'+String(x.supplierProductId||x.id)]?.ean||(x.ean&&x.ean!=='NEEDS MATCH'?<b>{x.ean}</b>:<span className="needsMatch">MISSING</span>)}</td><td>{saved[(x.supplier||x.source)+'-'+String(x.supplierProductId||x.id)]?.asin||x.asin||'—'}</td><td>{completed.includes((x.supplier||x.source)+'-'+String(x.supplierProductId||x.id))?<span className="identityBadge completed">COMPLETED</span>:<span className={'identityBadge '+x.identity}>{x.identity==='review'?'REVIEW':'UNMATCHED'}</span>}</td><td><span className="rowChevron">{selected?.id===x.id&&(selected.supplier||selected.source)===(x.supplier||x.source)?'⌃':'⌄'}</span></td></tr>{selected?.id===x.id&&(selected.supplier||selected.source)===(x.supplier||x.source)&&<tr className="catalogueInlineDetailRow"><td colSpan={7}><div className="identityEditor"><div><small>SUPPLIER RECORD</small><h2>{x.product}</h2><p>{x.supplier||x.source} · {x.rawTitle||x.product}</p></div><div className="identityEditGrid"><label>EAN / UPC<input value={draft.ean} onChange={e=>setDraft({...draft,ean:e.target.value})} placeholder="Enter or paste barcode"/></label><label>Amazon ASIN<input value={draft.asin} onChange={e=>setDraft({...draft,asin:e.target.value.toUpperCase()})} placeholder="e.g. B0XXXXXXXX"/></label><label>Brand<input value={draft.brand} onChange={e=>setDraft({...draft,brand:e.target.value})}/></label><label>Size / weight<input value={draft.size} onChange={e=>setDraft({...draft,size:e.target.value})}/></label><label>Amazon pack quantity<input type="number" min="1" value={amazonPackQty} onChange={e=>setAmazonPackQty(Math.max(1,Number(e.target.value)||1))}/></label></div><div className="identityEditorActions"><button className="secondaryAction" onClick={()=>openSellerAmp(x)}>{sasCopied?'✓ Copied · SellerAmp opened':'Check SellerAmp ↗'}</button><button className="secondaryAction" disabled={!draft.ean||looking} onClick={()=>barcodeLookup(x)}>{looking?'Looking up…':'Look up barcode'}</button><button className="secondaryAction" disabled={!draft.asin} onClick={()=>checkAsin(x)}>Check ASIN</button><button className="primary" disabled={!draft.asin||saving} onClick={()=>createMaster(x)}>{saving?'Saving…':'Create Master + Amazon Listing'}</button><button className="secondaryAction" disabled={!draft.ean||!draft.asin||(!asinCheck&&!completed.includes((x.supplier||x.source)+'-'+String(x.supplierProductId||x.id)))||saving} onClick={()=>complete(x)}>{completed.includes((x.supplier||x.source)+'-'+String(x.supplierProductId||x.id))?'Save legacy record':'Save legacy record'}</button></div>{completed.includes((x.supplier||x.source)+'-'+String(x.supplierProductId||x.id))&&saved[(x.supplier||x.source)+'-'+String(x.supplierProductId||x.id)]?.updated_at&&<small>Last updated {new Date(saved[(x.supplier||x.source)+'-'+String(x.supplierProductId||x.id)].updated_at).toLocaleString('en-GB')}</small>}{asinCheck&&<div className={'asinCheck '+asinCheck.status.toLowerCase()}><b>ASIN CHECK · {asinCheck.status}</b><span>{asinCheck.message}</span></div>}{lookup&&<div className="lookupResult">{lookup.error?<b>{lookup.error}</b>:<><div className="lookupResultHead">{lookup.image&&<img src={lookup.image} alt=""/>}<div><small>BARCODE LOOKUP CANDIDATE</small><h3>{lookup.title}</h3><span>{lookup.brand||'Brand unknown'}{lookup.size?' · '+lookup.size:''}</span></div><strong className={'confidence '+lookup.confidence.toLowerCase()}>{lookup.confidence} · {lookup.score}%</strong></div><div className="identityChecks"><span>{lookup.checks.barcode?'✓':'✕'} Barcode</span><span>{lookup.checks.brand?'✓':'○'} Brand</span><span>{lookup.checks.title?'✓':'○'} Product</span><span>{lookup.checks.size?'✓':'○'} Size</span><span>{lookup.asin?'✓ ASIN '+lookup.asin:'○ ASIN not returned'}</span></div>{lookup.asin&&<button className="secondaryAction" onClick={()=>setDraft({...draft,asin:lookup.asin})}>Use ASIN {lookup.asin}</button>}</>}</div>}</div></td></tr>}</Fragment>)}</tbody></table></div>
 {!loading&&!filtered.length&&<div className="identityEmpty"><BookOpen size={24}/><div><b>No products in this view</b><span>Try another supplier or identity filter.</span></div></div>}
 </section></>}

function WholesaleCatalogue(){
 const [supplier,setSupplier]=useState('Stateside Distribution'); const [q,setQ]=useState(''); const [selected,setSelected]=useState<any>(null); const [catalogueFilter,setCatalogueFilter]=useState<'all'|'matched'|'favourites'|'brandReview'>('all');
 const openProduct=(x:any)=>{setSelected(s=>s?.id===x.id?null:x)}; const [favourites,setFavourites]=useState<string[]>([])
 const [stateside,setStateside]=useState<any[]>([]); const [sweetGlory,setSweetGlory]=useState<any[]>([]); const [wholesaleSweets,setWholesaleSweets]=useState<any[]>([]); const [kingsCandy,setKingsCandy]=useState<any[]>([]); const [americanCandy,setAmericanCandy]=useState<any[]>([]); const [candyCargo,setCandyCargo]=useState<any[]>([]); const [ycWholesale,setYcWholesale]=useState<any[]>([]); const [worldCandies,setWorldCandies]=useState<any[]>([]); const [americatessen,setAmericatessen]=useState<any[]>([]); const [hancocks,setHancocks]=useState<any[]>([]); const [costSort,setCostSort]=useState<'none'|'caseAsc'|'caseDesc'|'unitAsc'|'unitDesc'>('none'); const [catalogueLoading,setCatalogueLoading]=useState(true); const [syncing,setSyncing]=useState(false); const [syncError,setSyncError]=useState(''); const [syncTimes,setSyncTimes]=useState<Record<string,string>>({})
 useEffect(()=>{try{setFavourites(JSON.parse(localStorage.getItem('flip-lead-favourites')||'[]'))}catch{};(async()=>{try{
  const setters:Record<string,(rows:any[])=>void>={
    'stateside':setStateside,'sweet-glory':setSweetGlory,'wholesale-sweets':setWholesaleSweets,'kings-candy':setKingsCandy,
    'american-candy-n-drinks':setAmericanCandy,'candy-cargo':setCandyCargo,'yc-wholesale':setYcWholesale,
    'world-candies':setWorldCandies,'americatessen':setAmericatessen,'hancocks':setHancocks,
  }
  const specs=CATALOGUE_SUPPLIERS.map(s=>[s.slug,s.name,setters[s.slug]] as const)
  const responses=await Promise.all(specs.map(([slug])=>fetch('/api/suppliers/catalogue?supplier='+slug,{cache:'no-store'})))
  const payloads=await Promise.all(responses.map(r=>r.json()))
  const times:Record<string,string>={}
  payloads.forEach((data:any,i)=>{const [,name,setter]=specs[i];if(data.ok&&Array.isArray(data.offers))setter(data.offers);if(data.lastSync)times[name]=new Date(data.lastSync).toLocaleString('en-GB')})
  setSyncTimes(t=>({...t,...times}))
 }catch{}finally{setCatalogueLoading(false)}})()},[])
 const live=supplier==='Sweet & Glory'?sweetGlory:supplier==='Wholesale Sweets'?wholesaleSweets:supplier==="King's Candy"?kingsCandy:supplier==='American Candy N Drinks'?americanCandy:supplier==='Candy Cargo'?candyCargo:supplier==='Y&C Wholesale'?ycWholesale:supplier==='World Candies'?worldCandies:supplier==='Americatessen'?americatessen:supplier==='Hancocks'?hancocks:stateside; const all=live
 const products=all.filter((x:any)=>{const search=(x.product+' '+(x.brand||'')+' '+(x.size||'')+' '+(x.ean||'')).toLowerCase().includes(q.toLowerCase());const match=x.identityStatus==='completed'||(x.ean&&x.ean!=='NEEDS MATCH');const fav=favourites.includes(x.id);const brandReview=!String(x.brand||'').trim()&&!String(x.brandStatus||'').trim();return search&&(catalogueFilter==='all'||(catalogueFilter==='matched'&&match)||(catalogueFilter==='favourites'&&fav)||(catalogueFilter==='brandReview'&&brandReview))}).sort((a:any,b:any)=>{const fav=Number(favourites.includes(b.id))-Number(favourites.includes(a.id));if(costSort==='none')return fav;const rawA=costSort.startsWith('case')?Number(a.effectiveCasePrice??a.casePrice):Number(a.effectiveUnitCost??a.unitCost),rawB=costSort.startsWith('case')?Number(b.effectiveCasePrice??b.casePrice):Number(b.effectiveUnitCost??b.unitCost);const av=rawA>0?rawA:Number.POSITIVE_INFINITY,bv=rawB>0?rawB:Number.POSITIVE_INFINITY;if(av===Infinity&&bv===Infinity)return 0;if(av===Infinity)return 1;if(bv===Infinity)return -1;return costSort.endsWith('Asc')?av-bv:bv-av})
 const matched=all.filter((x:any)=>x.ean&&x.ean!=='NEEDS MATCH').length; const identityMatched=all.filter((x:any)=>x.identityStatus==='completed'||x.identityStatus==='verified').length; const missingBrand=all.filter((x:any)=>!String(x.brand||'').trim()&&!String(x.brandStatus||'').trim()).length; const toggleFavourite=(id:string)=>{const next=favourites.includes(id)?favourites.filter(x=>x!==id):[...favourites,id];setFavourites(next);localStorage.setItem('flip-lead-favourites',JSON.stringify(next))}
 async function reviewBrand(x:any,status:'verified'|'unbranded'){let brand='';if(status==='verified'){brand=(window.prompt('Confirmed brand for '+x.product,x.brand||'')||'').trim();if(!brand)return}try{const r=await fetch('/api/suppliers/brand-review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({supplier:x.supplier||supplier,supplierProductId:x.supplierProductId,status,brand})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Unable to save brand');const patch=(rows:any[])=>rows.map(v=>v.id===x.id?{...v,brand:d.offer.brand,brandStatus:d.offer.brand_status}:v);if(supplier==='Sweet & Glory')setSweetGlory(patch);else if(supplier==='Wholesale Sweets')setWholesaleSweets(patch);else if(supplier==="King's Candy")setKingsCandy(patch);else if(supplier==='American Candy N Drinks')setAmericanCandy(patch);else if(supplier==='Candy Cargo')setCandyCargo(patch);else if(supplier==='Y&C Wholesale')setYcWholesale(patch);else if(supplier==='World Candies')setWorldCandies(patch);else if(supplier==='Americatessen')setAmericatessen(patch);else if(supplier==='Hancocks')setHancocks(patch);else setStateside(patch);setSelected((v:any)=>v?.id===x.id?{...v,brand:d.offer.brand,brandStatus:d.offer.brand_status}:v)}catch(e:any){setSyncError(e.message||'Unable to save brand review')}}
 async function syncSupplier(){setSyncing(true);setSyncError('');try{const isSweet=supplier==='Sweet & Glory';const isWholesaleSweets=supplier==='Wholesale Sweets';const isKings=supplier==="King's Candy";const isAmerican=supplier==='American Candy N Drinks';const isCargo=supplier==='Candy Cargo';const isYC=supplier==='Y&C Wholesale';const isWorld=supplier==='World Candies';const isAmericatessen=supplier==='Americatessen';const isHancocks=supplier==='Hancocks';const r=await fetch(isSweet?'/api/suppliers/sweet-glory':isWholesaleSweets?'/api/suppliers/wholesale-sweets':isKings?'/api/suppliers/kings-candy':isAmerican?'/api/suppliers/american-candy-n-drinks':isCargo?'/api/suppliers/candy-cargo':isYC?'/api/suppliers/yc-wholesale':isWorld?'/api/suppliers/world-candies':isAmericatessen?'/api/suppliers/americatessen':isHancocks?'/api/suppliers/hancocks':'/api/suppliers/stateside',{cache:'no-store'});const raw=await r.text();let d:any;try{d=JSON.parse(raw)}catch{throw new Error(r.ok?'Supplier returned an invalid response':'Supplier sync request failed ('+r.status+'). '+raw.slice(0,120))}if(!r.ok||!d.ok)throw new Error(d.error||'Sync failed');if(!Array.isArray(d.offers)||!d.offers.length)throw new Error('Sync returned no offers — previous catalogue kept');const stamp=new Date().toLocaleString('en-GB');if(isSweet)setSweetGlory(d.offers);else if(isWholesaleSweets)setWholesaleSweets(d.offers);else if(isKings)setKingsCandy(d.offers);else if(isAmerican)setAmericanCandy(d.offers);else if(isCargo)setCandyCargo(d.offers);else if(isYC)setYcWholesale(d.offers);else if(isWorld)setWorldCandies(d.offers);else if(isAmericatessen)setAmericatessen(d.offers);else if(isHancocks)setHancocks(d.offers);else setStateside(d.offers);setSyncTimes({...syncTimes,[supplier]:stamp});setSelected(null)}catch(e:any){setSyncError(e.message||'Unable to sync supplier')}finally{setSyncing(false)}}
 return <><div className="catalogueHero"><Title k="WHOLESALE INTELLIGENCE" t="Supplier Catalogue" p="One product. Many supplier offers. Sync live supplier data, then compare landed cost across wholesalers."/><div className="catalogueActions"><div className="syncAction"><button className="primary" onClick={syncSupplier} disabled={syncing}><Zap size={15}/>{syncing?' Syncing…':' Sync '+supplier}</button><small>{syncTimes[supplier]?'Last synced '+syncTimes[supplier]:'Not synced yet'}</small></div></div></div>
 <div className="catalogueToolbar"><div><small>SUPPLIER</small><select value={supplier} onChange={e=>setSupplier(e.target.value)}><option>Stateside Distribution</option><option>Sweet &amp; Glory</option><option>Wholesale Sweets</option><option>King&apos;s Candy</option><option>American Candy N Drinks</option><option>Candy Cargo</option><option>Y&amp;C Wholesale</option><option>World Candies</option><option>Americatessen</option><option>Hancocks</option></select></div><div><small>CATALOGUE</small><b>All products · In stock</b></div><div><small>CATALOGUE STATUS</small><b>{catalogueLoading?'LOADING…':live.length?'LIVE SYNC · '+live.length+' OFFERS':'NO SAVED OFFERS'}</b></div><div><small>SUPPLIER TERMS</small><b>{supplier==='Sweet & Glory'?'No minimum · stock + expiry supplied':supplier==='Wholesale Sweets'?'Public catalogue · prices VAT inclusive':supplier==="King's Candy"?'Public wholesale catalogue · BBD where supplied':supplier==='World Candies'?'£100 + VAT min · public catalogue · verify displayed VAT basis':supplier==='Y&C Wholesale'?'Trade pricing required · identity catalogue':supplier==='Americatessen'?'No minimum · delivery applies below threshold':supplier==='Hancocks'?'Trade wholesale · public case pricing':'Prices ex VAT · £50 min · £300 free mainland delivery'}</b></div></div>
 {syncError&&<div className="syncError"><AlertCircle size={15}/><div><b>Supplier sync could not complete</b><span>{syncError}. Existing verified records have been kept.</span></div></div>}
 <div className="catalogueStats"><button className="metric" onClick={()=>setCatalogueFilter('all')}><span>In stock</span><strong>{catalogueLoading?'—':all.length}</strong><small>{catalogueLoading?'loading saved catalogue':'current supplier products'}</small></button><button className="metric" onClick={()=>setCatalogueFilter('matched')}><span>EAN matched</span><strong>{catalogueLoading?'—':matched}</strong><small>{catalogueLoading?'loading identities':(all.length-matched)+' need barcode match'}</small></button><button className="metric" onClick={()=>setCatalogueFilter('all')}><span>Product Identity</span><strong>{catalogueLoading?'—':identityMatched}</strong><small>{catalogueLoading?'loading identities':(all.length-identityMatched)+' identities to complete'}</small></button><button className="metric" onClick={()=>setCatalogueFilter('brandReview')}><span>Brand review</span><strong>{catalogueLoading?'—':missingBrand}</strong><small>unreviewed missing brands</small></button></div>
 <section className="catalogueSection"><div className="overviewSectionHead"><div><small>{supplier.toUpperCase()} · ALL IN-STOCK</small><h2>Product catalogue</h2><p>{syncTimes[supplier]?'Last synced '+syncTimes[supplier]:'Run Sync to load the live supplier catalogue.'}</p></div><div className="catalogueSearch"><select value={costSort} onChange={e=>setCostSort(e.target.value as any)}><option value="none">Default order</option><option value="caseAsc">Case cost · low to high</option><option value="caseDesc">Case cost · high to low</option><option value="unitAsc">Unit cost · low to high</option><option value="unitDesc">Unit cost · high to low</option></select><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search product, EAN, brand or size…"/></div></div>
 <div className="catalogueTable"><table><thead><tr><th>★</th><th>Product</th><th>Identity</th><th>EAN / UPC</th><th>Case</th><th>Case cost</th><th>Unit cost</th><th>Source</th><th>Availability</th><th>Details</th></tr></thead><tbody>{products.map((x:any)=><Fragment key={x.id}><tr onClick={()=>openProduct(x)} className={selected?.id===x.id?'selected':''}><td><button className="supplierMore" title="Favourite" onClick={e=>{e.stopPropagation();toggleFavourite(x.id)}}><Star size={15} fill={favourites.includes(x.id)?'currentColor':'none'}/></button></td><td><div className="productCell"><b>{x.product}</b><span>{x.brand||'Brand not supplied'}{x.size?' · '+x.size:''}</span><small>{x.rawTitle&&x.rawTitle!==x.product?'Supplier listing: '+x.rawTitle:'Stateside catalogue offer'}</small></div></td><td>{x.identityStatus==='completed'?<span className="identityBadge confirmed">CONFIRMED</span>:x.ean&&x.ean!=='NEEDS MATCH'?<span className="identityBadge review">EAN SUPPLIED</span>:<span className="identityBadge unmatched">UNMATCHED</span>}</td><td>{x.ean&&x.ean!=='NEEDS MATCH'?<b>{x.ean}</b>:<span className="needsMatch">NEEDS MATCH</span>}</td><td>{x.caseQty} × {x.size||'unit'}</td><td><b>{priceOrUnavailable(x.effectiveCasePrice??x.casePrice)}</b><small>{usablePrice(x.casePrice)?(x.priceBasis==='EX VAT'?gbp(x.casePrice)+' ex VAT · effective inc VAT':'supplier price'):'identity-only record · not usable for economics'}</small></td><td><b>{priceOrUnavailable(x.effectiveUnitCost??x.unitCost??((usablePrice(x.casePrice)&&Number(x.caseQty)>0)?x.casePrice/x.caseQty:0))}</b><small>{usablePrice(x.effectiveUnitCost??x.unitCost??0)?(x.priceBasis==='EX VAT'?'effective inc VAT':'calculated'):'not priced'}</small></td><td><small>{supplier==='Sweet & Glory'?(x.expiry||x.source):x.source}</small></td><td><span className="stockPill">{x.stockQty?x.stockQty+' IN STOCK':x.status}</span></td><td><button className="supplierMore" onClick={e=>{e.stopPropagation();openProduct(x)}}>View</button></td></tr>{selected?.id===x.id&&<tr className="catalogueInlineDetailRow"><td colSpan={10}>{selected&&<section className="catalogueDetail"><div className="catalogueDetailHead"><div><small>MASTER PRODUCT + SUPPLIER OFFER</small><h2>{x.product} <span>{x.size}</span></h2><p>{x.brand||(x.brandStatus==='unbranded'?'Confirmed unbranded':'Brand not supplied')}</p>{!x.brand&&x.brandStatus!=='unbranded'&&<div className="quick"><button onClick={()=>reviewBrand(x,'verified')}>Verify brand</button><button onClick={()=>reviewBrand(x,'unbranded')}>Mark unbranded</button></div>}</div><button className="reset" onClick={e=>{e.stopPropagation();setSelected(null)}}>Close</button></div><div className="identityPanel"><div className="identityPanelHead"><div><small>PRODUCT IDENTITY</small><b>{x.identityStatus==='verified'||x.identityStatus==='completed'?'SellerAmp match verified':x.identityStatus==='rejected'?'SellerAmp match rejected':x.ean&&x.ean!=='NEEDS MATCH'?'Supplier EAN supplied · review required':'Identity needs matching'}</b></div>{x.identityStatus==='verified'||x.identityStatus==='completed'?<span className="identityBadge confirmed">VERIFIED</span>:x.identityStatus==='rejected'?<span className="identityBadge unmatched">WRONG MATCH</span>:x.ean&&x.ean!=='NEEDS MATCH'?<span className="identityBadge review">EAN SUPPLIED</span>:<span className="identityBadge unmatched">UNMATCHED</span>}</div><div className="identityChecks"><span>{x.ean&&x.ean!=='NEEDS MATCH'?'✓':'○'} EAN / UPC {x.ean&&x.ean!=='NEEDS MATCH'?'supplied':'needed'}</span><span>{x.brand?'✓':'○'} Brand {x.brand?'supplied':'not supplied'}</span><span>✓ Product name supplied</span><span>{x.size?'✓':'○'} Size {x.size?'supplied':'needs review'}</span><span>○ Amazon ASIN not linked</span></div><p>Flip Lead will only link supplier and Amazon listings when the product identity agrees. Ambiguous barcode, brand, variant, size or pack matches must be reviewed rather than silently merged.</p></div><div className="offerGrid"><Fact l="EAN / UPC" v={x.ean&&x.ean!=='NEEDS MATCH'?x.ean:'NEEDS MATCH'}/><Fact l="Supplier" v={x.supplier||x.source}/><Fact l="Supplier SKU" v={x.supplierSku||'Not supplied'}/><Fact l="Case quantity" v={String(x.caseQty)}/><Fact l="Case cost" v={usablePrice(x.effectiveCasePrice??x.casePrice)?gbp(Number(x.effectiveCasePrice??x.casePrice))+(x.priceBasis==='EX VAT'?' inc VAT':''):'Price unavailable'}/><Fact l="Unit cost" v={priceOrUnavailable(x.effectiveUnitCost??x.unitCost??((usablePrice(x.casePrice)&&Number(x.caseQty)>0)?x.casePrice/x.caseQty:0))}/><Fact l="Availability" v={x.status}/><Fact l="Last checked" v={x.checked?new Date(x.checked).toLocaleString('en-GB'):'26 Sep 2026'}/></div><div className="matchEmpty"><div><b>Supplier Match</b><span>No competing supplier offers matched yet. Supplier #2 will compare unit cost, landed cost, MOQ, delivery and expiry against this exact product.</span></div><a href={x.url} target="_blank" rel="noreferrer">Open source product ↗</a></div></section>}</td></tr>}</Fragment>)}</tbody></table></div>
 <div className="catalogueFoot"><span>{catalogueLoading?'LOADING SUPPLIER DATA':live.length?'LIVE SUPPLIER DATA':'NO SAVED SUPPLIER DATA'}</span><p>Supplier data is retained with source and sync time. Prices and availability can change; refresh before an order is placed.</p></div></section>
 
 <div className="catalogueNext"><BookOpen size={18}/><div><b>Cross-supplier architecture ready.</b><span>EAN/UPC is the primary match key. Name + brand + exact size may suggest matches, but Flip Lead will not silently merge uncertain products.</span></div></div></>}

